2. Pobieranie danych z API w partiach:async IAsyncEnumerable<Product> GetProductsFromApiAsync(int pageSize = 100)
{
    using var client = new HttpClient();
    int page = 0;
    bool hasMoreData = true;

    while (hasMoreData)
    {
        var response = await client.GetStringAsync(
            $"https://api.example.com/products?page={page}&size={pageSize}"
        );

        var products = JsonSerializer.Deserialize<List<Product>>(response);

        if (products == null || products.Count == 0)
        {
