Asynchroniczne strumienie są idealnym rozwiązaniem dla scenariuszy, w których dane są generowane lub pobierane stopniowo, a ich przetwarzanie może rozpocząć się przed pobraniem wszystkich elementów.

using System;
using System.Threading;
using System.Threading.Tasks;

class ThreadPoolMonitor
{
    static void Main()
    {
        Console.WriteLine("=== Monitoring ThreadPool ===\n");

        // Wyświetlenie początkowego stanu
        PrintThreadPoolStats();

        // Dodanie wielu zadań do puli wątków
        var tasks = new Task[20];
        for (int i = 0; i < tasks.Length; i++)
        {
            int taskId = i;
            tasks[i] = Task.Run(() =>
            {
                Console.WriteLine($"Zadanie {taskId} rozpoczęte w wątku {Thread.CurrentThread.ManagedThreadId}");

                // Wyświetlenie statystyk podczas wykonywania
                PrintThreadPoolStats();

                // Symulacja długotrwałej operacji
                Thread.Sleep(2000);

                Console.WriteLine($"Zadanie {taskId} zakończone");
            });

            // Krótka przerwa między dodawaniem zadań
            Thread.Sleep(100);
        }

        Console.WriteLine("\nOczekiwanie na zakończenie wszystkich zadań...\n");
        Task.WaitAll(tasks);

        // Wyświetlenie końcowego stanu
        Thread.Sleep(500);
        Console.WriteLine("\n=== Stan końcowy ===");
        PrintThreadPoolStats();
    }

    static void PrintThreadPoolStats()
    {
        Console.WriteLine($"[{DateTime.Now:HH:mm:ss.fff}] " +
                          $"ThreadCount: {ThreadPool.ThreadCount}, " +
                          $"PendingWorkItemCount: {ThreadPool.PendingWorkItemCount}");
    }
}

