AutoResetEvent - używany dla ekskluzywnego dostępu do zasobu przez wątek (tylko jeden wątek z grupy wątków oczekująch po wywołaniu WaitOne() jest wybudzony i otrzymuje dostęp do zasobu)  class BasicWaitHandle
  {
      static EventWaitHandle _waitHandle = new AutoResetEvent (false);

      static void Main()
      {
          new Thread (Waiter).Start();
          Thread.Sleep (1000);                  // Pause for a second...
          _waitHandle.Set();                    // Wake up the Waiter.
      }

      static void Waiter()
      {
          Console.WriteLine ("Waiting...");
          _waitHandle.WaitOne();                // Wait for notification
          Console.WriteLine ("Notified");
      } 
  }


